/**
 * Rejects creating an owner whose E.164 telephone is already used by another owner,
 * answering 409. Kept as its own advice so this rule stays a small, self-contained unit
 * rather than growing the controller or another handler.
 */
@ControllerAdvice
@Order(Ordered.HIGHEST_PRECEDENCE)
public class OwnerUniqueTelephoneAdvice extends RequestBodyAdviceAdapter {

    private final ClinicService clinicService;

    public OwnerUniqueTelephoneAdvice(ClinicService clinicService) {
        this.clinicService = clinicService;
    }

    @Override
    public boolean supports(MethodParameter methodParameter, Type targetType,
                            Class<? extends HttpMessageConverter<?>> converterType) {
        Method method = methodParameter.getMethod();
        return OwnerFieldsDto.class.equals(targetType)
            && method != null && "addOwner".equals(method.getName());
