    @ResponseBody
    public ResponseEntity<String> handleDuplicateTelephone(DuplicateTelephoneException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());
    }

    /** Signals a telephone already used by another owner. */
